export default async function(self, env, ctx) {
  const values = [3, 1, 4, 1, 5];
  const odds = values.filter(function (n) {
    return n % 2 !== 0;
  });
  odds.sort(function (a, b) {
    return a - b;
  });
  let sum = 0;
  for (let i = 0; i < odds.length; i += 1) {
    sum += odds[i];
  }
  return sum;
}

