function sortStrings(xs: string[]) -> string[] {
  let n = xs.length();
  let i = 0;
  while (i < n) {
    let j = i + 1;
    while (j < n) {
      if (xs[j] < xs[i]) {
        let tmp = xs[i];
        xs[i] = xs[j];
        xs[j] = tmp;
      }
      j = j + 1;
    }
    i = i + 1;
  }
  xs
}

